/**
 * @method
 * @name search
 * @description search 처리
 * @returns {void}
 * @hidden N
 */
scwin.search = function () {
    $c.util.getComponent('form_5').submit();
};

/**
 * @method
 * @name setCheckYn
 * @description set Check Yn 처리
 * @param {*} object object
 * @returns {void}
 * @hidden N
 */
scwin.setCheckYn = function (object) {
    if (object.checked) {
        $c.util.getComponent('form_5').checkYn.value = '1';
    } else {
        $c.util.getComponent('form_5').checkYn.value = "0";
    }
};
